function decodeHalf(encoded) {
  const bytes = atob(encoded), values = new Float32Array(bytes.length / 2);
  for (let i = 0; i < values.length; i++)
    values[i] = DataUtils.fromHalfFloat(bytes.charCodeAt(i * 2) | (bytes.charCodeAt(i * 2 + 1) << 8));
  return values;
}
export function interferenceTableData() {
  return { phase: decodeHalf(phaseBase64), energy: decodeHalf(energyBase64),
    metadata: { thicknessNm: 300, phaseWidth: 1024, energyWidth: 128, energyHeight: 32,
      averageEntry: 0.6796511718023437 } };
}
